"use client";

import {
  BookOpenIcon,
  MagnifyingGlassIcon,
  SparkleIcon,
} from "@phosphor-icons/react";
import { useEffect, useRef, useState } from "react";
import { Autocomplete } from "../../../components/vip-ui/autocomplete";
import { Badge } from "../../../components/vip-ui/badge";
import { Button } from "../../../components/vip-ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "../../../components/vip-ui/card";
import { CopyButton } from "../../../components/vip-ui/copy-button";
import { ListBox, ListBoxItem } from "../../../components/vip-ui/list-box";
import {
  Response,
  ResponseActions,
  ResponseContent,
  ResponseFooter,
} from "../../../components/vip-ui/response";
import { SearchField } from "../../../components/vip-ui/search-field";
import { Skeleton } from "../../../components/vip-ui/skeleton";
import { SourceLink } from "../../../components/vip-ui/source-link";
import { TextScramble } from "../../../components/vip-ui/text-scramble";
import {
  answerFor,
  answerText,
  defaultQuery,
  popularQueries,
  type SearchResult,
  suggestions,
} from "./data";

const loadingLabels = [
  "READING GUIDES",
  "CHECKING API REFERENCES",
  "MATCHING SOURCES",
];

export function AiSearch() {
  const [query, setQuery] = useState(defaultQuery);
  const [result, setResult] = useState<SearchResult>(() =>
    answerFor(defaultQuery),
  );
  const [loading, setLoading] = useState(false);
  const [phase, setPhase] = useState(0);
  const [suggestionsOpen, setSuggestionsOpen] = useState(false);
  const searchRef = useRef<HTMLDivElement>(null);
  const timers = useRef<number[]>([]);

  useEffect(
    () => () => {
      for (const id of timers.current) window.clearTimeout(id);
    },
    [],
  );

  useEffect(() => {
    if (!suggestionsOpen) return;
    const onPointerDown = (event: PointerEvent) => {
      if (!searchRef.current?.contains(event.target as Node)) {
        setSuggestionsOpen(false);
      }
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setSuggestionsOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [suggestionsOpen]);

  function startSearch(value: string) {
    const next = value.trim() || defaultQuery;
    for (const id of timers.current) window.clearTimeout(id);
    setQuery(next);
    setResult(answerFor(next));
    setSuggestionsOpen(false);
    setLoading(true);
    setPhase(0);
    timers.current = [
      window.setTimeout(() => setPhase(1), 380),
      window.setTimeout(() => setPhase(2), 760),
      window.setTimeout(() => setLoading(false), 1150),
    ];
  }

  function focusSearch() {
    searchRef.current?.querySelector("input")?.focus();
    setSuggestionsOpen(true);
  }

  return (
    <div className="min-h-svh bg-muted/40 px-4 py-8 sm:px-6 lg:py-12">
      <div className="mx-auto w-full max-w-3xl">
        <header className="relative isolate text-center">
          <div
            aria-hidden="true"
            className="pointer-events-none absolute inset-x-0 -top-24 -z-10 mx-auto h-80 max-w-2xl rounded-full opacity-70 blur-3xl"
            style={{
              background:
                "radial-gradient(50% 50% at 50% 50%, color-mix(in oklab, var(--chart-3) 18%, transparent) 0%, transparent 70%)",
            }}
          />
          <span
            aria-hidden="true"
            className="mx-auto grid size-11 place-items-center rounded-xl bg-primary text-primary-foreground shadow-[var(--shadow-float)]"
          >
            <BookOpenIcon size={22} weight="fill" />
          </span>
          <p className="mt-4 text-xs font-medium tracking-[0.18em] text-muted-foreground uppercase">
            Fernway docs
          </p>
          <h1 className="mt-2 text-[clamp(1.875rem,4vw,2.75rem)] leading-[1.1] font-semibold tracking-[-0.045em] text-balance">
            Get the answer,{" "}
            <span className="text-muted-foreground">not the page.</span>
          </h1>
          <p className="mx-auto mt-3 max-w-xl text-[15px] leading-6 text-muted-foreground">
            Search guides, API references, and release notes.
          </p>
        </header>

        <div ref={searchRef} className="relative z-20 mx-auto mt-8 max-w-2xl">
          <Autocomplete>
            <SearchField
              aria-label="Search the docs"
              size="lg"
              placeholder="Ask a question about Fernway"
              value={query}
              onChange={(value) => {
                setQuery(value);
                setSuggestionsOpen(value.trim().length > 0);
              }}
              onFocus={() => {
                if (query.trim()) setSuggestionsOpen(true);
              }}
              onSubmit={(value) => startSearch(value)}
            />
            {suggestionsOpen && (
              <div className="absolute inset-x-0 top-full z-30 mt-2">
                <ListBox
                  aria-label="Suggested searches"
                  items={suggestions}
                  onAction={(key) => {
                    const suggestion = suggestions.find(
                      (item) => item.id === String(key),
                    );
                    if (suggestion) startSearch(suggestion.label);
                  }}
                  className="max-h-72 shadow-[var(--shadow-float)]"
                >
                  {(item) => (
                    <ListBoxItem
                      id={item.id}
                      textValue={`${item.label} ${item.category}`}
                      className="gap-3"
                    >
                      <span className="flex min-w-0 flex-1 items-center gap-2.5">
                        <MagnifyingGlassIcon
                          size={15}
                          aria-hidden="true"
                          className="shrink-0 text-muted-foreground"
                        />
                        <span className="truncate">{item.label}</span>
                      </span>
                      <span className="shrink-0 text-xs text-muted-foreground">
                        {item.category}
                      </span>
                    </ListBoxItem>
                  )}
                </ListBox>
              </div>
            )}
          </Autocomplete>
        </div>

        <div className="mt-3 flex flex-wrap items-center justify-center gap-2">
          <span className="text-xs text-muted-foreground">Popular</span>
          {popularQueries.map((item) => (
            <Button
              key={item}
              variant="outline"
              size="xs"
              onPress={() => startSearch(item)}
            >
              {item}
            </Button>
          ))}
        </div>

        <div className="mt-8">
          {loading ? (
            <Card className="p-5 sm:p-6" aria-busy="true">
              <div className="flex flex-wrap items-center justify-between gap-3">
                <span
                  aria-live="polite"
                  className="flex items-center gap-2 text-xs font-medium tracking-[0.16em] text-muted-foreground uppercase"
                >
                  <span className="size-1.5 rounded-full bg-primary motion-safe:animate-pulse" />
                  <TextScramble value={loadingLabels[phase]} duration={0.4} />
                </span>
                <Badge variant="outline">Searching</Badge>
              </div>
              <div className="mt-5 grid gap-2.5" aria-hidden="true">
                <Skeleton className="h-3 w-11/12" />
                <Skeleton className="h-3 w-4/5" />
                <Skeleton className="h-3 w-2/3" />
              </div>
              <div
                className="mt-5 grid gap-2 sm:grid-cols-3"
                aria-hidden="true"
              >
                <Skeleton className="h-16" />
                <Skeleton className="h-16" />
                <Skeleton className="h-16" />
              </div>
            </Card>
          ) : (
            <>
              <Card>
                <CardHeader>
                  <div className="flex flex-wrap items-start justify-between gap-3">
                    <div className="grid min-w-0 gap-1">
                      <p className="text-xs font-medium text-muted-foreground">
                        Answer
                      </p>
                      <CardTitle as="h2" className="text-base">
                        {result.title}
                      </CardTitle>
                      <CardDescription>{result.updated}</CardDescription>
                    </div>
                    <Badge variant="accent" className="gap-1">
                      <SparkleIcon size={12} weight="fill" aria-hidden="true" />
                      AI answer
                    </Badge>
                  </div>
                </CardHeader>
                <CardContent>
                  <Response status="complete">
                    <ResponseContent className="grid gap-3">
                      {result.blocks.map((block) => {
                        const key =
                          block.type === "paragraph"
                            ? block.text
                            : block.items.join("|");
                        return block.type === "paragraph" ? (
                          <p key={key}>{block.text}</p>
                        ) : (
                          <ul
                            key={key}
                            className="grid list-disc gap-1.5 ps-5 marker:text-muted-foreground"
                          >
                            {block.items.map((item) => (
                              <li key={item}>{item}</li>
                            ))}
                          </ul>
                        );
                      })}
                      {result.code && (
                        <div className="min-w-0 overflow-hidden rounded-lg border border-border/70 bg-muted/60">
                          <div className="flex items-center justify-between gap-2 border-b border-border/60 px-3 py-1.5">
                            <span className="text-xs font-medium text-muted-foreground">
                              Shell
                            </span>
                            <CopyButton
                              value={result.code}
                              iconOnly
                              variant="ghost"
                              size="xs"
                              aria-label="Copy code"
                            />
                          </div>
                          <pre className="overflow-x-auto p-3 font-mono text-xs leading-5 whitespace-pre">
                            {result.code}
                          </pre>
                        </div>
                      )}
                    </ResponseContent>
                    <ResponseActions>
                      <CopyButton
                        value={answerText(result)}
                        variant="ghost"
                        size="sm"
                      />
                      <Button variant="ghost" size="sm" onPress={focusSearch}>
                        <MagnifyingGlassIcon size={16} aria-hidden="true" />
                        New search
                      </Button>
                    </ResponseActions>
                    <ResponseFooter className="grid gap-2 pt-2">
                      <p className="text-xs font-medium text-muted-foreground">
                        {result.sources.length} sources
                      </p>
                      {result.sources.map((source, index) => (
                        <SourceLink
                          key={source.href}
                          href={source.href}
                          label={source.label}
                          source={source.source}
                          description={source.description}
                          index={index + 1}
                          className="gap-2.5 p-2.5"
                        />
                      ))}
                    </ResponseFooter>
                  </Response>
                </CardContent>
              </Card>

              <div className="mt-4 flex flex-wrap items-center gap-2">
                <span className="text-xs text-muted-foreground">Related</span>
                {result.related.map((item) => (
                  <Button
                    key={item}
                    variant="outline"
                    size="xs"
                    onPress={() => startSearch(item)}
                  >
                    {item}
                  </Button>
                ))}
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

export type AnswerBlock =
  | { type: "paragraph"; text: string }
  | { type: "list"; items: string[] };

export interface AnswerSource {
  label: string;
  source: string;
  href: string;
  description: string;
}

export interface SearchResult {
  title: string;
  blocks: AnswerBlock[];
  code?: string;
  updated: string;
  sources: AnswerSource[];
  related: string[];
}

export const defaultQuery = "How do I rotate an API key?";

export const popularQueries = [
  "Rotate an API key",
  "Set up SSO",
  "Webhook retries",
  "Usage limits",
];

export const suggestions = [
  { id: "api-keys", label: "Rotate an API key", category: "API keys" },
  { id: "sso", label: "Set up SSO", category: "Security" },
  { id: "webhooks", label: "Webhook retries", category: "Webhooks" },
  { id: "usage", label: "Usage limits", category: "Billing" },
  { id: "invite", label: "Invite a teammate", category: "Members" },
  { id: "audit", label: "Audit log events", category: "Security" },
];

export function answerFor(query: string): SearchResult {
  const text = query.toLowerCase();
  if (text.includes("sso") || text.includes("saml") || text.includes("scim")) {
    return {
      title: "Set up single sign-on",
      updated: "Updated Oct 22, 2026",
      blocks: [
        {
          type: "paragraph",
          text: "SSO is available on the Business plan.",
        },
        {
          type: "list",
          items: [
            "Open Settings → Security → SSO.",
            "Select your identity provider and paste the metadata URL.",
            "Test with one account before you enforce SSO.",
            "Turn on Require SSO to block password sign-in.",
            "Turn on SCIM after SSO works.",
          ],
        },
        {
          type: "paragraph",
          text: "Next step: set a default role for new members.",
        },
      ],
      sources: [
        {
          label: "Single sign-on",
          source: "docs.fernway.app/security/sso",
          href: "https://docs.fernway.app/security/sso",
          description: "Supported providers, metadata, and test steps.",
        },
        {
          label: "SCIM provisioning",
          source: "docs.fernway.app/security/scim",
          href: "https://docs.fernway.app/security/scim",
          description: "Sync members and groups from your identity provider.",
        },
        {
          label: "Security overview",
          source: "docs.fernway.app/security",
          href: "https://docs.fernway.app/security",
          description: "SSO, SCIM, audit logs, and session policy.",
        },
      ],
      related: [
        "Require SSO for everyone",
        "Set up SCIM",
        "Change the default role",
      ],
    };
  }

  if (text.includes("webhook") || text.includes("delivery")) {
    return {
      title: "How webhook retries work",
      updated: "Updated Oct 18, 2026",
      blocks: [
        {
          type: "paragraph",
          text: "Fernway retries failed deliveries 5 times in 2 hours.",
        },
        {
          type: "list",
          items: [
            "Retries run after 10s, 1m, 5m, 30m, and 2h.",
            "A delivery fails without a 2xx response in 10 seconds.",
            "Each retry keeps the same event ID.",
            "After the fifth retry, the event expires.",
          ],
        },
        {
          type: "paragraph",
          text: "Next step: return 2xx as soon as you store the event.",
        },
      ],
      code: `curl -X POST https://api.fernway.app/v1/webhooks \\
  -H "Fernway-Signature: t=...,v1=..." \\
  -d '{"event":"member.created"}'`,
      sources: [
        {
          label: "Webhooks",
          source: "docs.fernway.app/webhooks",
          href: "https://docs.fernway.app/webhooks",
          description: "Events, payloads, and delivery order.",
        },
        {
          label: "Verify a signature",
          source: "docs.fernway.app/webhooks/signatures",
          href: "https://docs.fernway.app/webhooks/signatures",
          description: "Check the timestamp and HMAC on each request.",
        },
        {
          label: "Delivery log",
          source: "docs.fernway.app/webhooks/logs",
          href: "https://docs.fernway.app/webhooks/logs",
          description: "Inspect retries, response codes, and expiry.",
        },
      ],
      related: [
        "Verify a webhook signature",
        "Why did a webhook expire?",
        "Replay a failed delivery",
      ],
    };
  }

  if (
    text.includes("usage") ||
    text.includes("limit") ||
    text.includes("quota")
  ) {
    return {
      title: "API usage limits",
      updated: "Updated Oct 29, 2026",
      blocks: [
        {
          type: "paragraph",
          text: "The Pro plan includes 250,000 API requests each month.",
        },
        {
          type: "list",
          items: [
            "The limit resets at the start of each billing period.",
            "Usage counts successful and failed requests.",
            "At 100%, new requests return 429.",
            "The Business plan includes 1,000,000 requests.",
          ],
        },
        {
          type: "paragraph",
          text: "Next step: set a usage alert in Settings → Billing.",
        },
      ],
      sources: [
        {
          label: "Rate limits",
          source: "docs.fernway.app/reference/rate-limits",
          href: "https://docs.fernway.app/reference/rate-limits",
          description: "Request limits, headers, and 429 responses.",
        },
        {
          label: "Plans and usage",
          source: "fernway.app/pricing",
          href: "https://fernway.app/pricing",
          description: "Request limits for each plan.",
        },
      ],
      related: [
        "Raise the request limit",
        "Set a usage alert",
        "Check current usage",
      ],
    };
  }

  if (
    text.includes("invite") ||
    text.includes("member") ||
    text.includes("teammate")
  ) {
    return {
      title: "Invite a teammate",
      updated: "Updated Oct 12, 2026",
      blocks: [
        {
          type: "paragraph",
          text: "Open Settings → Members, choose Invite, and add email addresses.",
        },
        {
          type: "list",
          items: [
            "Pick a role before you send the invite.",
            "Owner is limited to one person.",
            "The invite expires after 7 days.",
            "SSO members skip the invite email.",
          ],
        },
        {
          type: "paragraph",
          text: "Next step: change a role at any time from the member row.",
        },
      ],
      sources: [
        {
          label: "Members and roles",
          source: "docs.fernway.app/members",
          href: "https://docs.fernway.app/members",
          description: "Invite, remove, and change roles.",
        },
        {
          label: "SSO sign-in",
          source: "docs.fernway.app/security/sso",
          href: "https://docs.fernway.app/security/sso",
          description: "How SSO members join a workspace.",
        },
      ],
      related: ["Change a member role", "Remove a member", "Resend an invite"],
    };
  }

  if (text.includes("audit") || text.includes("siem")) {
    return {
      title: "Audit log events",
      updated: "Updated Oct 24, 2026",
      blocks: [
        {
          type: "paragraph",
          text: "The audit log records sign-ins, key rotations, role changes, and billing changes.",
        },
        {
          type: "list",
          items: [
            "Business plan logs stay for 1 year.",
            "Each event has an actor, an IP address, and a timestamp.",
            "Keys and tokens appear as IDs, never as secrets.",
            "Export the log as CSV or stream it to your SIEM.",
          ],
        },
        {
          type: "paragraph",
          text: "Next step: open Settings → Audit log to filter events.",
        },
      ],
      sources: [
        {
          label: "Audit log",
          source: "docs.fernway.app/reference/audit-log",
          href: "https://docs.fernway.app/reference/audit-log",
          description: "Events, retention, and export.",
        },
        {
          label: "Activity events",
          source: "docs.fernway.app/reference/events",
          href: "https://docs.fernway.app/reference/events",
          description: "The full event name list.",
        },
      ],
      related: [
        "Export the audit log",
        "Stream events to a SIEM",
        "Who rotated a key?",
      ],
    };
  }

  if (
    text.includes("api key") ||
    text.includes("rotate") ||
    text.includes("revoke") ||
    text.includes("key")
  ) {
    return {
      title: "Rotate an API key",
      updated: "Updated Oct 30, 2026",
      blocks: [
        {
          type: "paragraph",
          text: "Open Settings → API keys, select the key, and choose Rotate.",
        },
        {
          type: "list",
          items: [
            "The old key stays active for 24 hours.",
            "Copy the new key before you close the dialog.",
            "Deploy the new key to each service.",
            "Revoke the old key after the last healthy request.",
          ],
        },
        {
          type: "paragraph",
          text: "Next step: check the audit log for the rotation event.",
        },
      ],
      code: `fernway keys rotate --id key_9f2c --grace 24h`,
      sources: [
        {
          label: "API keys",
          source: "docs.fernway.app/guides/api-keys",
          href: "https://docs.fernway.app/guides/api-keys",
          description: "Create, rotate, and revoke keys.",
        },
        {
          label: "Authentication",
          source: "docs.fernway.app/reference",
          href: "https://docs.fernway.app/reference/authentication",
          description: "Headers, scopes, and error codes.",
        },
        {
          label: "Audit log",
          source: "docs.fernway.app/reference/audit-log",
          href: "https://docs.fernway.app/reference/audit-log",
          description: "Key rotation events and retention.",
        },
      ],
      related: [
        "Can I have more than one active key?",
        "How do I revoke a key?",
        "Why does a key stop working?",
      ],
    };
  }

  return {
    title: "Closest guides",
    updated: "Updated Oct 29, 2026",
    blocks: [
      {
        type: "paragraph",
        text: "No exact guide matched your question.",
      },
      {
        type: "paragraph",
        text: "Next step: try a shorter question with the feature name.",
      },
    ],
    sources: [
      {
        label: "Documentation home",
        source: "docs.fernway.app",
        href: "https://docs.fernway.app",
        description: "Guides, references, and release notes.",
      },
      {
        label: "API reference",
        source: "docs.fernway.app/reference",
        href: "https://docs.fernway.app/reference",
        description: "Endpoints, errors, and rate limits.",
      },
    ],
    related: ["Rotate an API key", "Set up SSO", "Webhook retries"],
  };
}

export function answerText(result: SearchResult) {
  const body = result.blocks
    .map((block) =>
      block.type === "paragraph"
        ? block.text
        : block.items.map((item) => `- ${item}`).join("\n"),
    )
    .join("\n\n");
  return `${result.title}\n\n${body}${result.code ? `\n\n${result.code}` : ""}`;
}

import { AiSearch } from "./ai-search";

export const metadata = {
  title: "Answer search",
  description: "Docs search that answers the question and lists sources.",
};

export default function AiSearchBlockPage() {
  return <AiSearch />;
}
